def transform(grid):
    # Colors sorted by bounding box perimeter or width/height descending
    colors = set(x for row in grid for x in row if x != 0)
    bbs = {}
    for c in colors:
        rows = [r for r in range(len(grid)) if c in grid[r]]
        cols = [col for r in range(len(grid)) for col in range(len(grid[0])) if grid[r][col] == c]
        bbs[c] = (max(rows) - min(rows) + 1) * (max(cols) - min(cols) + 1)
    sorted_colors = sorted(colors, key=lambda c: -bbs[c])
    return [sorted_colors]

def transform(grid):
    # Non-zero colors ordered by appearance from outer boundary to center (min distance to border)
    colors = set(x for row in grid for x in row if x != 0)
    dist = {}
    R, C = len(grid), len(grid[0])
    for c in colors:
        min_d = min(min(r, R - 1 - r, col, C - 1 - col) for r in range(R) for col in range(C) if grid[r][col] == c)
        dist[c] = min_d
    sorted_colors = sorted(colors, key=lambda c: dist[c])
    return [sorted_colors]

def transform(grid):
    # The middle row / slice of unique colors from left to center
    mid_row = grid[len(grid)//2]
    seen = []
    for x in mid_row[:len(mid_row)//2]:
        if x != 0 and x not in seen:
            seen.append(x)
    return [seen]

def transform(grid):
    # Non-zero colors in order of first appearance (reading order)
    seen = []
    for row in grid:
        for x in row:
            if x != 0 and x not in seen:
                seen.append(x)
    return [seen]
